-- Cryptid alpha: additive tables/RPCs; preserves existing rooms, profiles and ratings.
begin;
do $$declare definition text;begin
 select pg_get_constraintdef(oid) into definition from pg_constraint where conrelid='public.boardmate_rooms'::regclass and conname='boardmate_rooms_game_check';
 if definition is null then raise exception 'Existing game catalog constraint missing';end if;
 if position('''cryptid''' in definition)=0 then
  alter table public.boardmate_rooms drop constraint boardmate_rooms_game_check;
  execute 'alter table public.boardmate_rooms add constraint boardmate_rooms_game_check CHECK ('||substring(definition from 7)||' OR game=''cryptid'')';
 end if;
end $$;
create or replace function public.boardmate_game_max(p_game text) returns integer language sql immutable as $$
 select case when p_game='cryptid' then 5 when p_game in ('calico','cascadia','quacks','mandom','samurai','eldorado','panam','planetx','projectl') then 4 when p_game in ('pocketnova','plakoro','airlandsea') then 2 when p_game='thegame' then 5 when p_game='kraken' then 8 when p_game in ('fantasyrealms','fantasyrealmsgreek','powergrid') then 6 when p_game in ('avalon','secrethitler','onenightwerewolf') then 10 else 6 end;
$$;
create or replace function public.boardmate_game_min(p_game text) returns integer language sql immutable as $$
 select case when p_game='cryptid' then 3 when p_game in ('calico','cascadia','pocketnova','thegame','plakoro','quacks','mandom','samurai','eldorado','panam','projectl','airlandsea','planetx','fantasyrealms','fantasyrealmsgreek') then 2 when p_game in ('maskmen','acquire','kraken','powergrid','onenightwerewolf') then 3 when p_game in ('avalon','secrethitler') then 5 else 2 end;
$$;
create table if not exists public.boardmate_cryptid_catalog(id text primary key,advanced boolean not null,board jsonb not null,clues jsonb not null);
create table if not exists public.boardmate_cryptid_games(room_id uuid primary key references public.boardmate_rooms(id) on delete cascade,state jsonb not null,secrets jsonb not null,revision bigint not null default 1,updated_at timestamptz not null default now());
alter table public.boardmate_cryptid_catalog enable row level security;
alter table public.boardmate_cryptid_games enable row level security;
revoke all on public.boardmate_cryptid_catalog,public.boardmate_cryptid_games from public,anon,authenticated;

create or replace function public.create_boardmate_cryptid_room(p_token text,p_title text)
returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare uid uuid;rid uuid;nickname text;title text;begin
 uid:=public.boardmate_session_user(p_token);if uid is null then raise exception '로그인이 필요합니다.';end if;
 select p.nickname into nickname from public.boardmate_profiles p where p.user_id=uid;
 title:=left(trim(coalesce(p_title,'')),40);if title='' then title:=left(coalesce(nickname,'보드메이트')||'의 크립티드 한 판',40);end if;
 insert into public.boardmate_rooms(title,game,max_players,host_id,play_mode) values(title,'cryptid',5,uid,'turn') returning id into rid;
 insert into public.boardmate_room_members(room_id,user_id,seat) values(rid,uid,0);return rid;
end $$;

create or replace function public.boardmate_cryptid_intersection(p_clues jsonb,p_omit integer default -1)
returns integer[] language sql immutable set search_path=pg_catalog,public as $$
 select coalesce(array_agg(cell),'{}'::integer[]) from generate_series(0,107) cell where not exists(select 1 from jsonb_array_elements(p_clues) with ordinality c(value,ord) where ord-1<>p_omit and not(c.value->'allowed' @> jsonb_build_array(cell)));
$$;
create or replace function public.boardmate_cryptid_view(p_token text,p_room_id uuid)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare uid uuid;g public.boardmate_cryptid_games%rowtype;s jsonb;seat integer;status text;begin
 uid:=public.boardmate_session_user(p_token);if uid is null or not exists(select 1 from public.boardmate_room_members where room_id=p_room_id and user_id=uid) then raise exception '이 방의 참가자가 아닙니다.';end if;
 select r.status into status from public.boardmate_rooms r where r.id=p_room_id and r.game='cryptid';if not found then raise exception '크립티드 방이 아닙니다.';end if;
 select * into g from public.boardmate_cryptid_games where room_id=p_room_id;if not found then return jsonb_build_object('state',null,'revision',0,'clue',null,'roomStatus',status);end if;
 select ord::integer-1 into seat from jsonb_array_elements(g.state->'players') with ordinality p(value,ord) where p.value->>'user_id'=uid::text;
 if seat is null then raise exception '게임 참가자가 아닙니다.';end if;
 s:=g.state;
 if coalesce((s->>'over')::boolean,false) then s:=s||jsonb_build_object('revealedClues',(select jsonb_agg(c.value->>'text') from jsonb_array_elements(g.secrets->'clues') c));end if;
 return jsonb_build_object('state',s,'revision',g.revision,'clue',jsonb_build_object('id',g.secrets->'clues'->seat->>'id','text',g.secrets->'clues'->seat->>'text'),'seat',seat,'roomStatus',status);
end $$;

create or replace function public.boardmate_cryptid_init(p_token text,p_room_id uuid,p_advanced boolean default false)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare uid uuid;r public.boardmate_rooms%rowtype;catalog public.boardmate_cryptid_catalog%rowtype;n integer;players jsonb;chosen jsonb;ids integer[];s jsonb;valid boolean:=false;attempt integer;omit integer;begin
 uid:=public.boardmate_session_user(p_token);select * into r from public.boardmate_rooms where id=p_room_id for update;
 if uid is null or r.host_id is distinct from uid or r.game is distinct from 'cryptid' or r.status is distinct from 'playing' then raise exception '진행 중인 크립티드 방의 방장만 시작할 수 있습니다.';end if;
 if exists(select 1 from public.boardmate_cryptid_games where room_id=p_room_id) then return public.boardmate_cryptid_view(p_token,p_room_id);end if;
 select count(*),jsonb_agg(jsonb_build_object('user_id',m.user_id,'seat',m.seat,'name',p.nickname) order by m.seat) into n,players from public.boardmate_room_members m join public.boardmate_profiles p using(user_id) where m.room_id=p_room_id;
 if n not between 3 and 5 then raise exception '크립티드는 3~5인 게임입니다.';end if;
 select * into catalog from public.boardmate_cryptid_catalog where advanced=p_advanced order by random() limit 1;if not found then raise exception '크립티드 지도 업데이트가 필요합니다.';end if;
 for attempt in 1..4000 loop
  select jsonb_agg(c.value) into chosen from (select value from jsonb_array_elements(catalog.clues) order by random() limit n) c;
  ids:=public.boardmate_cryptid_intersection(chosen);if cardinality(ids)<>1 then continue;end if;
  valid:=true;for omit in 0..n-1 loop if cardinality(public.boardmate_cryptid_intersection(chosen,omit))=1 then valid:=false;exit;end if;end loop;
  if valid then exit;end if;
 end loop;
 if not valid then raise exception '단서 생성에 실패했습니다. 다시 시작해 주세요.';end if;
 s:=jsonb_build_object('kind','cryptid-alpha-v1','board',catalog.board,'players',players,'phase','sharing','current',0,'sharingCount',0,'turn',1,'marks','{}'::jsonb,'pending',null,'log','[]'::jsonb,'over',false,'winner',null);
 insert into public.boardmate_cryptid_games(room_id,state,secrets) values(p_room_id,s,jsonb_build_object('clues',chosen,'solution',ids[1]));
 update public.boardmate_rooms set turn_user_id=(players->0->>'user_id')::uuid,turn_updated_at=now() where id=p_room_id;
 return public.boardmate_cryptid_view(p_token,p_room_id);
end $$;

create or replace function public.boardmate_cryptid_legal(s jsonb,secrets jsonb,seat integer,cell integer,disc boolean)
returns boolean language sql immutable set search_path=pg_catalog,public as $$
 select cell between 0 and 107 and (s->'marks'->cell::text->>'cube') is null and not(coalesce(s->'marks'->cell::text->'discs','[]'::jsonb) @> jsonb_build_array(seat)) and ((secrets->'clues'->seat->'allowed' @> jsonb_build_array(cell))=disc);
$$;
create or replace function public.boardmate_cryptid_put(s jsonb,secret jsonb,seat integer,cell integer,disc boolean)
returns jsonb language plpgsql immutable set search_path=pg_catalog,public as $$
declare mark jsonb;begin
 if not public.boardmate_cryptid_legal(s,secret,seat,cell,disc) then raise exception '단서에 맞고 자신의 말이나 큐브가 없는 칸을 선택하세요.';end if;
 mark:=coalesce(s->'marks'->cell::text,jsonb_build_object('cube',null,'discs','[]'::jsonb));
 if disc then mark:=mark||jsonb_build_object('discs',mark->'discs'||jsonb_build_array(seat));else mark:=mark||jsonb_build_object('cube',seat);end if;
 return jsonb_set(s,array['marks',cell::text],mark,true);
end $$;
create or replace function public.boardmate_cryptid_next(s jsonb) returns jsonb language sql immutable as $$
 select s||jsonb_build_object('phase','turn','pending',null,'current',((s->>'current')::integer+1)%jsonb_array_length(s->'players'),'turn',(s->>'turn')::integer+1);
$$;

create or replace function public.boardmate_cryptid_action(p_token text,p_room_id uuid,p_expected_revision bigint,p_action jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare uid uuid;r public.boardmate_rooms%rowtype;g public.boardmate_cryptid_games%rowtype;s jsonb;secret jsonb;seat integer;n integer;cell integer;target integer;kind text;phase text;yes boolean;run_search boolean:=false;search_cell integer;k integer;other integer;log_text text;begin
 uid:=public.boardmate_session_user(p_token);select * into r from public.boardmate_rooms where id=p_room_id for update;
 if uid is null or r.game is distinct from 'cryptid' or r.status is distinct from 'playing' or not exists(select 1 from public.boardmate_room_members where room_id=p_room_id and user_id=uid) then raise exception '진행 중인 방의 참가자가 아닙니다.';end if;
 select * into g from public.boardmate_cryptid_games where room_id=p_room_id for update;if not found then raise exception '게임이 시작되지 않았습니다.';end if;
 if g.revision is distinct from p_expected_revision then raise exception 'revision conflict';end if;
 s:=g.state;secret:=g.secrets;n:=jsonb_array_length(s->'players');phase:=s->>'phase';kind:=p_action->>'type';
 select ord::integer-1 into seat from jsonb_array_elements(s->'players') with ordinality p(value,ord) where p.value->>'user_id'=uid::text;
 if seat is null or seat<>(s->>'current')::integer or coalesce((s->>'over')::boolean,false) then raise exception '현재 행동 차례가 아닙니다.';end if;
 cell:=(p_action->>'cell')::integer;if cell is null or cell not between 0 and 107 then raise exception '지도 칸을 확인하세요.';end if;
 log_text:=(s->'players'->seat->>'name')||' · '||chr(65+cell%12)||(cell/12+1)::text;
 if phase='sharing' and kind='cube' then
  s:=public.boardmate_cryptid_put(s,secret,seat,cell,false);s:=s||jsonb_build_object('sharingCount',(s->>'sharingCount')::integer+1,'current',(seat+1)%n);
  if (s->>'sharingCount')::integer=n*2 then s:=s||jsonb_build_object('phase','turn','current',0);end if;log_text:=log_text||' 초기 큐브';
 elsif phase='penalty' and kind='cube' then s:=public.boardmate_cryptid_put(s,secret,seat,cell,false);s:=public.boardmate_cryptid_next(s);log_text:=log_text||' 추가 큐브';
 elsif phase='search-offer' and kind='disc' then search_cell:=(s->'pending'->>'cell')::integer;s:=public.boardmate_cryptid_put(s,secret,seat,cell,true);run_search:=true;log_text:=log_text||' 추가 디스크';
 elsif phase='turn' and kind='question' then
  target:=(p_action->>'target')::integer;
  if target is null or target not between 0 and n-1 or target=seat or (s->'marks'->cell::text->>'cube') is not null or coalesce(s->'marks'->cell::text->'discs','[]'::jsonb) @> jsonb_build_array(target) then raise exception '질문할 상대와 칸을 다시 선택하세요.';end if;
  yes:=secret->'clues'->target->'allowed' @> jsonb_build_array(cell);s:=public.boardmate_cryptid_put(s,secret,target,cell,yes);
  log_text:=log_text||' → '||(s->'players'->target->>'name')||case when yes then ' 디스크' else ' 큐브' end;
  if yes then s:=public.boardmate_cryptid_next(s);else s:=s||jsonb_build_object('phase','penalty','pending',jsonb_build_object('cell',cell));end if;
 elsif phase='turn' and kind='search' then
  if (s->'marks'->cell::text->>'cube') is not null or not(secret->'clues'->seat->'allowed' @> jsonb_build_array(cell)) then raise exception '자신의 단서에 맞고 큐브가 없는 칸만 탐색할 수 있습니다.';end if;
  search_cell:=cell;log_text:=log_text||' 탐색';
  if coalesce(s->'marks'->cell::text->'discs','[]'::jsonb) @> jsonb_build_array(seat) then
   s:=s||jsonb_build_object('phase','search-offer','pending',jsonb_build_object('cell',cell));
   if not exists(select 1 from generate_series(0,107) c where public.boardmate_cryptid_legal(s,secret,seat,c,true)) then run_search:=true;end if;
  else s:=public.boardmate_cryptid_put(s,secret,seat,cell,true);run_search:=true;end if;
 else raise exception '지금 할 수 없는 행동입니다.';end if;
 if run_search then
  s:=s||jsonb_build_object('pending',null);
  for k in 1..n-1 loop
   other:=(seat+k)%n;if coalesce(s->'marks'->search_cell::text->'discs','[]'::jsonb) @> jsonb_build_array(other) then continue;end if;
   yes:=secret->'clues'->other->'allowed' @> jsonb_build_array(search_cell);s:=public.boardmate_cryptid_put(s,secret,other,search_cell,yes);
   if not yes then s:=s||jsonb_build_object('phase','penalty','pending',jsonb_build_object('cell',search_cell));exit;end if;
  end loop;
  if s->>'phase'<>'penalty' then s:=s||jsonb_build_object('phase','finished','over',true,'winner',seat,'pending',null);log_text:=log_text||' · 서식지 발견!';end if;
 end if;
 if s->>'phase'='penalty' and not exists(select 1 from generate_series(0,107) c where public.boardmate_cryptid_legal(s,secret,seat,c,false)) then s:=public.boardmate_cryptid_next(s);log_text:=log_text||' · 추가 큐브 칸 없음';end if;
 s:=jsonb_set(s,'{log}',jsonb_build_array(log_text)||coalesce(s->'log','[]'::jsonb));
 s:=jsonb_set(s,'{log}',(select coalesce(jsonb_agg(value),'[]'::jsonb) from (select value from jsonb_array_elements(s->'log') limit 80) l));
 update public.boardmate_cryptid_games set state=s,revision=revision+1,updated_at=now() where room_id=p_room_id;
 update public.boardmate_rooms set turn_user_id=case when (s->>'over')::boolean then null else (s->'players'->((s->>'current')::integer)->>'user_id')::uuid end,turn_updated_at=now(),status=case when (s->>'over')::boolean then 'finished' else status end,finished_at=case when (s->>'over')::boolean then now() else finished_at end where id=p_room_id;
 return public.boardmate_cryptid_view(p_token,p_room_id);
end $$;
revoke all on function public.boardmate_cryptid_intersection(jsonb,integer),public.boardmate_cryptid_legal(jsonb,jsonb,integer,integer,boolean),public.boardmate_cryptid_put(jsonb,jsonb,integer,integer,boolean),public.boardmate_cryptid_next(jsonb) from public,anon,authenticated;
revoke all on function public.create_boardmate_cryptid_room(text,text),public.boardmate_cryptid_view(text,uuid),public.boardmate_cryptid_init(text,uuid,boolean),public.boardmate_cryptid_action(text,uuid,bigint,jsonb) from public;
grant execute on function public.create_boardmate_cryptid_room(text,text),public.boardmate_cryptid_view(text,uuid),public.boardmate_cryptid_init(text,uuid,boolean),public.boardmate_cryptid_action(text,uuid,bigint,jsonb) to anon,authenticated;
-- Catalog seed is appended by qa/generate-cryptid-catalog.mjs. It contains all
-- public rule predicates, never the randomly assigned clues or a live solution.
-- CRYPTID_CATALOG_SEED
insert into public.boardmate_cryptid_catalog(id,advanced,board,clues) select value->>'id',(value->>'advanced')::boolean,value->'board',value->'clues' from jsonb_array_elements($cryptidseed$[{"id":"normal-1","advanced":false,"board":{"width":12,"height":9,"cells":[{"id":0,"col":0,"row":0,"terrain":"desert","animal":null,"tile":2},{"id":1,"col":1,"row":0,"terrain":"mountain","animal":null,"tile":2},{"id":2,"col":2,"row":0,"terrain":"mountain","animal":null,"tile":2},{"id":3,"col":3,"row":0,"terrain":"mountain","animal":null,"tile":2,"structure":{"kind":"shack","colour":"white"}},{"id":4,"col":4,"row":0,"terrain":"mountain","animal":null,"tile":2},{"id":5,"col":5,"row":0,"terrain":"swamp","animal":null,"tile":2},{"id":6,"col":6,"row":0,"terrain":"forest","animal":"cougar","tile":4},{"id":7,"col":7,"row":0,"terrain":"forest","animal":null,"tile":4},{"id":8,"col":8,"row":0,"terrain":"forest","animal":null,"tile":4,"structure":{"kind":"stone","colour":"green"}},{"id":9,"col":9,"row":0,"terrain":"desert","animal":null,"tile":4},{"id":10,"col":10,"row":0,"terrain":"desert","animal":null,"tile":4},{"id":11,"col":11,"row":0,"terrain":"desert","animal":null,"tile":4},{"id":12,"col":0,"row":1,"terrain":"desert","animal":null,"tile":2},{"id":13,"col":1,"row":1,"terrain":"desert","animal":null,"tile":2},{"id":14,"col":2,"row":1,"terrain":"desert","animal":null,"tile":2},{"id":15,"col":3,"row":1,"terrain":"forest","animal":null,"tile":2},{"id":16,"col":4,"row":1,"terrain":"swamp","animal":null,"tile":2},{"id":17,"col":5,"row":1,"terrain":"swamp","animal":null,"tile":2},{"id":18,"col":6,"row":1,"terrain":"water","animal":"cougar","tile":4},{"id":19,"col":7,"row":1,"terrain":"water","animal":null,"tile":4},{"id":20,"col":8,"row":1,"terrain":"water","animal":null,"tile":4},{"id":21,"col":9,"row":1,"terrain":"mountain","animal":null,"tile":4},{"id":22,"col":10,"row":1,"terrain":"desert","animal":null,"tile":4},{"id":23,"col":11,"row":1,"terrain":"desert","animal":null,"tile":4},{"id":